/* @lc app=leetcode id=3341 lang=kotlin */ class Solution { fun minTimeToReach(moveTime: Array<IntArray>): Int = moveTime.size.let { n -> moveTime[0].size.let { m -> LongArray(n * m) { Long.MAX_VALUE }.also { it[0] = 0L }.let { d -> java.util.PriorityQueue<LongArray>(compareBy<LongArray> { it[0] }).also { it.add(longArrayOf(0L, 0L)) }.let { pq -> generateSequence { pq.poll() }.filter { (t, s) -> t == d[s.toInt()] }.forEach { (t, s) -> s.toInt().let { c -> listOf(c / m + 1 to c % m, c / m - 1 to c % m, c / m to c % m + 1, c / m to c % m - 1).filter { (a, b) -> a in 0 until n && b in 0 until m }.forEach { (a, b) -> (maxOf(t, moveTime[a][b].toLong()) + 1).let { nt -> if (nt < d[a * m + b]) pq.add(longArrayOf(nt, (a * m + b).toLong())).also { d[a * m + b] = nt } } } } }.let { d[n * m - 1].toInt() } } } } } }